# Pub/Sub broker with topic filtering
class PubSubBroker:
    def __init__(self):
        self._topics = {}

    def subscribe(self, topic, handler):
        self._topics.setdefault(topic, []).append(handler)
        print(f'Subscribed {handler.__name__} to topic "{topic}"')

    def publish(self, topic, message):
        handlers = self._topics.get(topic, [])
        print(f'Publishing to "{topic}": {message}  ({len(handlers)} subscriber(s))')
        for h in handlers:
            h(message)

broker = PubSubBroker()

def analytics_handler(msg): print(f'  [Analytics] logged event: {msg["event"]}')
def audit_handler(msg):     print(f'  [Audit]     stored record: {msg}')
def alert_handler(msg):     print(f'  [Alert]     paging on-call for {msg["event"]}')

broker.subscribe('user.signup', analytics_handler)
broker.subscribe('user.signup', audit_handler)
broker.subscribe('payment.failed', alert_handler)
broker.subscribe('payment.failed', audit_handler)

broker.publish('user.signup',    {'event': 'user.signup',    'user': 'bob'})
broker.publish('payment.failed', {'event': 'payment.failed', 'order': 55})
